import styles from "./page.module.css";

export default function Home() {
  return (
    <main className={styles.main}>
      <section className={styles.hero}>
        <h1>안녕하세요, 미니멀 개발자입니다.</h1>
        <p>복잡함을 덜어내고 본질에 집중하는 웹 환경을 만듭니다.</p>
      </section>
    </main>
  );
}

.main {
  max-width: 1200px;
  margin: 0 auto;
  padding: 4rem 2rem;
  min-height: calc(100vh - 200px); /* Adjust for header/footer */
  display: flex;
  align-items: center;
}

.hero h1 {
  font-size: 2.5rem;
  margin-bottom: 1rem;
  font-weight: 700;
}

.hero p {
  font-size: 1.1rem;
  color: #666;
}

.headerContainer {
  height: 72px;
  background-color: var(--background);
  border-bottom: 1px solid var(--border);
  position: sticky;
  top: 0;
  z-index: 100;
}

.header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  height: 100%;
  padding: 0 2rem;
  max-width: 1200px;
  margin: 0 auto;
}

.logo {
  font-weight: 700;
  font-size: 1.25rem;
  color: var(--text-main);
}

.nav ul {
  display: flex;
  gap: 2.5rem;
}

.nav a {
  font-size: 0.95rem;
  font-weight: 500;
  color: var(--text-sub);
  transition: color 0.2s;
}

.nav a.active {
  color: var(--primary);
}

.nav a:hover {
  color: var(--primary);
}

.resumeBtn {
  background-color: var(--primary);
  color: #fff;
  padding: 0.6rem 1.2rem;
  border-radius: 8px;
  font-size: 0.9rem;
  font-weight: 600;
  transition: opacity 0.2s;
}

.resumeBtn:hover {
  opacity: 0.9;
}

.aboutSection {
  max-width: 1200px;
  margin: 0 auto;
  padding: 80px 2rem;
  display: grid;
  grid-template-columns: 1fr 1.5fr;
  gap: 80px;
  align-items: start;
}

.imageArea {
  position: relative;
}

.placeholderImage {
  width: 100%;
  aspect-ratio: 3 / 4;
  background-color: #eee;
  border-radius: 16px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #aaa;
  font-weight: 500;
}

.imageInfo {
  margin-top: 1.5rem;
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.location {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  font-size: 0.9rem;
  color: var(--text-sub);
}

.socialButtons {
  display: flex;
  gap: 0.75rem;
}

.iconBtn {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  border: 1px solid var(--border);
  display: flex;
  align-items: center;
  justify-content: center;
  background: none;
  cursor: pointer;
  transition: all 0.2s;
}

.iconBtn:hover {
  border-color: var(--primary);
  color: var(--primary);
}

.contentArea {
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}

.label {
  display: inline-block;
  padding: 0.4rem 0.8rem;
  background-color: var(--primary-light);
  color: var(--primary);
  font-size: 0.75rem;
  font-weight: 700;
  border-radius: 100px;
  letter-spacing: 0.05em;
  width: fit-content;
}

.headline {
  font-size: 3rem;
  line-height: 1.2;
  font-weight: 700;
  color: var(--text-main);
}

.headline strong {
  color: var(--primary);
}

.description {
  font-size: 1.1rem;
  color: var(--text-sub);
  line-height: 1.7;
  display: flex;
  flex-direction: column;
  gap: 1rem;
  max-width: 600px;
}

.infoGrid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 2rem;
  margin-top: 2rem;
}

.infoItem h4 {
  font-size: 1rem;
  font-weight: 700;
  margin-bottom: 0.5rem;
}

.infoItem p {
  font-size: 0.95rem;
  color: var(--text-sub);
  white-space: pre-line;
}

.ctaBox {
  margin-top: 3rem;
  padding: 2rem;
  background-color: var(--primary-light);
  border-radius: 16px;
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.ctaText h4 {
  font-size: 1.1rem;
  font-weight: 700;
  margin-bottom: 0.25rem;
}

.ctaText p {
  font-size: 0.95rem;
  color: var(--text-sub);
}

.downloadBtn {
  background-color: var(--primary);
  color: #fff;
  padding: 0.8rem 1.5rem;
  border-radius: 8px;
  font-weight: 600;
  font-size: 0.95rem;
}

@media (max-width: 960px) {
  .aboutSection {
    grid-template-columns: 1fr;
    gap: 40px;
  }
}

import AboutSection from "@/components/About/AboutSection";

export default function Home() {
  return (
    <main>
      <AboutSection />
    </main>
  );
}

